solution:
public static bool IsBalanced(string expression)
{
    var stack = new Stack<char>();
    foreach (char c in expression)
    {
        if (c is '(' or '[' or '{')
        {
            stack.Push(c);
            continue;
        }
        var opening = c switch { ')' => '(', ']' => '[', '}' => '{', _ => '\0' };
        if (opening != '\0' && (!stack.TryPop(out var last) || opening != last))
            return false;
    }
    return stack.Count == 0;
}

