solution:
public static int LongestUnique(string text)
{
    int[] last = new int[128];
    Array.Fill(last, -1);
    int left = 0, best = 0;
    for (int right = 0; right < text.Length; right++)
    {
        char c = text[right];
        left = Math.Max(left, last[c] + 1);
        last[c] = right;
        best = Math.Max(best, right - left + 1);
    }
    return best;
}

