public static int FewestHops(int n, int[][] edges, int source, int target)
{
    var next = new List<int>?[n];
    foreach (var edge in edges)
        (next[edge[0]] ??= []).Add(edge[1]);

    var distance = new int[n];
    Array.Fill(distance, -1);
    distance[source] = 0;
    var queue = new Queue<int>();
    queue.Enqueue(source);
    while (queue.TryDequeue(out int current))
    {
        if (current == target) return distance[current];
        if (next[current] is not { } adjacent) continue;
        foreach (int node in adjacent)
        {
            if (distance[node] >= 0) continue;
            distance[node] = distance[current] + 1;
            queue.Enqueue(node);
        }
    }
    return -1;
}

