solution:
public static int[] MatchCodes(int[] left, int[] right)
{
    var available = new Dictionary<int, int>();
    foreach (int code in right) available[code] = available.GetValueOrDefault(code) + 1;
    var result = new List<int>();
    foreach (int code in left)
    {
        if (available.GetValueOrDefault(code) == 0) continue;
        result.Add(code);
        available[code]--;
    }
    return result.ToArray();
}

