    FROM #Sales
)
SELECT order_id, warehouse FROM Prices WHERE amount > mean_amount ORDER BY order_id;

WITH Sequence AS (
    SELECT invoice_no, LEAD(invoice_no) OVER (ORDER BY invoice_no) AS next_no FROM #Invoices
)
SELECT invoice_no + 1 AS first_missing, next_no - 1 AS last_missing
FROM Sequence WHERE next_no - invoice_no > 1 ORDER BY first_missing;

