DECLARE @qty int = 4;
WHILE @qty IS NOT NULL
BEGIN
    BEGIN TRANSACTION;
    UPDATE #Bins SET stock = stock - @qty WHERE bin = 1 AND stock >= @qty;
    IF @@ROWCOUNT = 1
    BEGIN
        UPDATE #Bins SET stock = stock + @qty WHERE bin = 2;
        IF @@ROWCOUNT = 1 COMMIT TRANSACTION; ELSE ROLLBACK TRANSACTION;
    END
    ELSE ROLLBACK TRANSACTION;
    SET @qty = CASE WHEN @qty = 4 THEN 20 END;
END;
SELECT bin, stock FROM #Bins ORDER BY bin;
